16	import { ECDSA } from "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
17	import { MessageHashUtils } from "@openzeppelin/contracts/utils/cryptography/MessageHashUtils.sol";
18	import { Pausable } from "@openzeppelin/contracts/utils/Pausable.sol";
19	import { Initializable } from "@solady/src/utils/Initializable.sol";
20	import { MerkleProofLib } from "@solady/src/utils/MerkleProofLib.sol";
21	import { SafeTransferLib } from "@solady/src/utils/SafeTransferLib.sol";
22	
23	import { Constants } from "../utils/Constants.sol";
24	import { Errors } from "../utils/Errors.sol";
25	
26	import { ILegionAddressRegistry } from "../interfaces/registries/ILegionAddressRegistry.sol";
27	import { ILegionAbstractSale } from "../interfaces/sales/ILegionAbstractSale.sol";
28	import { ILegionVesting } from "../interfaces/vesting/ILegionVesting.sol";
29	
30	import { LegionPositionManager } from "../position/LegionPositionManager.sol";
31	import { LegionVestingManager } from "../vesting/LegionVestingManager.sol";
32	
33	/**
34	 * @title Legion Abstract Sale
35	 * @author Legion
36	 * @notice Provides core functionality for token sales in the Legion Protocol.
37	 * @dev Abstract base contract that implements common sale operations including investments, refunds, token
38	 * distribution, and position management using soulbound NFTs.
39	 */
40	abstract contract LegionAbstractSale is
41	    ILegionAbstractSale,
42	    LegionVestingManager,
43	    LegionPositionManager,
44	    Initializable,
45	    Pausable
46	{
47	    using ECDSA for bytes32;
48	    using MessageHashUtils for bytes32;
49	
50	    /// @dev Struct containing the sale configuration
51	    LegionSaleConfiguration internal s_saleConfig;
52	
53	    /// @dev Struct containing the sale addresses configuration
54	    LegionSaleAddressConfiguration internal s_addressConfig;
55	
56	    /// @dev Struct tracking the current sale status
57	    LegionSaleStatus internal s_saleStatus;
58	
59	    /// @dev Mapping of position IDs to their respective positions
60	    mapping(uint256 s_positionId => InvestorPosition s_investorPosition) internal s_investorPositions;
61	
62	    /// @notice Restricts function access to the Legion bouncer only.
63	    /// @dev Reverts if the caller is not the configured Legion bouncer.
64	    modifier onlyLegion() {
65	        if (msg.sender != s_addressConfig.legionBouncer) revert Errors.LegionSale__NotCalledByLegion();
66	        _;
67	    }
68	
69	    /// @notice Restricts function access to the project admin only.
70	    /// @dev Reverts if the caller is not the configured project admin.
71	    modifier onlyProject() {
72	        if (msg.sender != s_addressConfig.projectAdmin) revert Errors.LegionSale__NotCalledByProject();
73	        _;
74	    }
75	
76	    /// @notice Restricts function access to either Legion bouncer or project admin.
77	    /// @dev Reverts if the caller is neither project admin nor Legion bouncer.
78	    modifier onlyLegionOrProject() {
79	        if (msg.sender != s_addressConfig.projectAdmin && msg.sender != s_addressConfig.legionBouncer) {
80	            revert Errors.LegionSale__NotCalledByLegionOrProject();
81	        }
82	        _;
83	    }
84	
85	    /// @notice Restricts interaction to when the sale is canceled.
86	    /// @dev Reverts if the sale is not canceled.
87	    modifier whenSaleCanceled() {
88	        // Verify that the sale is canceled
89	        _verifySaleIsCanceled();
90	        _;
91	    }
92	
93	    /// @notice Restricts interaction to when the sale is not canceled.
94	    /// @dev Reverts if the sale is canceled.
95	    modifier whenSaleNotCanceled() {
96	        // Verify that the sale is not canceled
97	        _verifySaleNotCanceled();
98	        _;
99	    }
100	

